def create_order_state_machine(initial_state: str = "PENDING") -> object:
    """Create an order state machine instance.

    Business rules (states and events):
      - States: PENDING -> PAID -> SHIPPED -> DELIVERED
      - Cancellation: PENDING -> CANCELLED, PAID -> CANCELLED
      - Terminal states: DELIVERED and CANCELLED (no further transitions)
      - Events: pay, ship, deliver, cancel

    The returned object provides:
      - .state (property): current state as an uppercase string
      - .transition(event): perform a transition and return the new state
      - .allowed_events(): list of allowed event strings from the current state
      - .history(): tuple of visited states including the initial state
      - .is_terminal(): whether current state is terminal
      - .InvalidTransitionError: exception type raised for invalid transitions

    Error handling:
      - If event is not a string: TypeError
      - If event is unknown (not one of pay/ship/deliver/cancel): ValueError
      - If event is known but not allowed from the current state: InvalidTransitionError
      - If initial_state is not a supported state: ValueError

    Normalization:
      - initial_state is normalized with strip() and upper()
      - event is normalized with strip() and lower()
    """

    class InvalidTransitionError(Exception):
        """Raised when a known event is not allowed from the current state."""

    class OrderStateMachine:
        _TRANSITIONS = {
            "PENDING": {"pay": "PAID", "cancel": "CANCELLED"},
            "PAID": {"ship": "SHIPPED", "cancel": "CANCELLED"},
            "SHIPPED": {"deliver": "DELIVERED"},
            "DELIVERED": {},
            "CANCELLED": {},
        }

        _ALL_EVENTS = {"pay", "ship", "deliver", "cancel"}

        def __init__(self, state: str):
            if not isinstance(state, str):
                raise TypeError("initial_state must be a string")
            normalized = state.strip().upper()
            if normalized not in self._TRANSITIONS:
                raise ValueError(f"Unsupported initial_state: {state!r}")
            self._state = normalized
            self._history = [normalized]
            # Expose the exception type so tests can reference it without importing.
            self.InvalidTransitionError = InvalidTransitionError

        @property
        def state(self) -> str:
            return self._state

        def is_terminal(self) -> bool:
            return self._state in {"DELIVERED", "CANCELLED"}

        def allowed_events(self) -> list[str]:
            allowed = self._TRANSITIONS.get(self._state, {})
            # Deterministic ordering helps both callers and tests.
            return sorted(allowed.keys())

        def history(self) -> tuple[str, ...]:
            # Return an immutable snapshot.
            return tuple(self._history)

        def transition(self, event: str) -> str:
            if not isinstance(event, str):
                raise TypeError("event must be a string")
            ev = event.strip().lower()
            if ev not in self._ALL_EVENTS:
                raise ValueError(f"Unknown event: {event!r}")

            allowed = self._TRANSITIONS.get(self._state, {})
            if ev not in allowed:
                raise InvalidTransitionError(
                    f"Event {ev!r} not allowed from state {self._state!r}. "
                    f"Allowed events: {sorted(allowed.keys())}"
                )

            next_state = allowed[ev]
            self._state = next_state
            self._history.append(next_state)
            return next_state

        def __repr__(self) -> str:
            return f"OrderStateMachine(state={self._state!r}, history_len={len(self._history)})"

    return OrderStateMachine(initial_state)

